module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire s0_not, s1_not;
    wire d0_enable, d1_enable, d2_enable, d3_enable;

    // Generate NOT signals for select inputs
    assign s0_not = ~sel[0];
    assign s1_not = ~sel[1];

    // Generate enable signals for each data input
    assign d0_enable = s1_not & s0_not & in[0];
    assign d1_enable = s1_not & sel[0] & in[1];
    assign d2_enable = sel[1] & s0_not & in[2];
    assign d3_enable = sel[1] & sel[0] & in[3];

    // Combine enable signals to form the output
    assign out = d0_enable | d1_enable | d2_enable | d3_enable;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire s0_not, s1_not;
    wire y0, y1, y2, y3;

    // Generate inverted select signals
    assign s0_not = ~sel[0];
    assign s1_not = ~sel[1];

    // Generate enable signals for each input
    assign y0 = in[0] & s1_not & s0_not;
    assign y1 = in[1] & s1_not & sel[0];
    assign y2 = in[2] & sel[1] & s0_not;
    assign y3 = in[3] & sel[1] & sel[0];

    // Combine enable signals to produce the output
    assign out = y0 | y1 | y2 | y3;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire n_sel0, n_sel1;
    wire y0, y1, y2, y3;

    // Generate inverted select signals
    not (n_sel0, sel[0]);
    not (n_sel1, sel[1]);

    // Generate enable signals for each input
    and (y0, in[0], n_sel1, n_sel0);
    and (y1, in[1], n_sel1, sel[0]);
    and (y2, in[2], sel[1], n_sel0);
    and (y3, in[3], sel[1], sel[0]);

    // Combine enable signals to produce output
    or (out, y0, y1, y2, y3);

endmodule

module mux4to1 (
    input [3:0] in,
