    and (y0, in[0], s0_not, s1_not);
    and (y1, in[1], sel[0], s1_not);
    and (y2, in[2], s0_not, sel[1]);
    and (y3, in[3], sel[0], sel[1]);

    or (out, y0, y1, y2, y3);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire s0, s1, ns0, ns1;
wire y0, y1, y2, y3;

assign s0 = sel[0];
assign s1 = sel[1];

assign ns0 = ~s0;
assign ns1 = ~s1;

assign y0 = in[0] & ns1 & ns0;
assign y1 = in[1] & ns1 & s0;
assign y2 = in[2] & s1 & ns0;
assign y3 = in[3] & s1 & s0;

assign out = y0 | y1 | y2 | y3;

endmodule

