module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire s0_not, s1_not;
    wire y0, y1, y2, y3;

    // Generate NOT signals for select inputs
    assign s0_not = ~sel[0];
    assign s1_not = ~sel[1];

    // Generate enable signals and combine with input data
    assign y0 = in[0] & s1_not & s0_not;
    assign y1 = in[1] & s1_not & sel[0];
    assign y2 = in[2] & sel[1] & s0_not;
    assign y3 = in[3] & sel[1] & sel[0];

    // Combine all enable signals to form the output
    assign out = y0 | y1 | y2 | y3;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire s0, s1, s0_n, s1_n;
    wire y0, y1, y2, y3;

    assign s0 = sel[0];
    assign s1 = sel[1];
    assign s0_n = ~s0;
    assign s1_n = ~s1;

    assign y0 = in[0] & s0_n & s1_n;
    assign y1 = in[1] & s0 & s1_n;
    assign y2 = in[2] & s0_n & s1;
    assign y3 = in[3] & s0 & s1;

    assign out = y0 | y1 | y2 | y3;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire nsel0, nsel1;
wire y0, y1, y2, y3;

not (nsel0, sel[0]);
not (nsel1, sel[1]);

and (y0, in[0], nsel1, nsel0);
and (y1, in[1], nsel1, sel[0]);
and (y2, in[2], sel[1], nsel0);
and (y3, in[3], sel[1], sel[0]);

or (out, y0, y1, y2, y3);

endmodule

