module fsm_3state (
    input clk, reset,
    output reg [1:0] state
);

    // State encoding
    localparam A = 2'b00;
    localparam B = 2'b01;
    localparam C = 2'b10;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= A;  // Reset to state A
        end else begin
            case (state)
                A: state <= B;  // Transition from A to B
                B: state <= C;  // Transition from B to C
                C: state <= A;  // Transition from C to A
                default: state <= A;  // Default to state A
            endcase
        end
    end
endmodule

