module traffic_light (
    input clk, reset,
    output [2:0] light
);

    reg [1:0] state;
    reg [2:0] light_reg;

    assign light = light_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
            light_reg <= 3'b001; // Red light
