module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output reg [1:0] state
);

    // State encoding
    parameter IDLE = 2'b00, COLLECTING_COINS = 2'b01, DISPENSING_ITEM = 2'b10;

    reg [1:0] current_state, next_state;
    reg [3:0] coin_count; // Assume up to 15 coins can be tracked

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
            coin_count <= 4'b0000;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state; // Default to no state change
        case (current_state)
            IDLE: begin
                if (coin_inserted) begin
                    next_state = COLLECTING_COINS;
                end
            end
            COLLECTING_COINS: begin
                if (coin_inserted) begin
                    if (coin_count == 4'b1111) begin
                        next_state = DISPENSING_ITEM;
                    end
                end else if (item_selected) begin
                    if (coin_count >= 4'b0100) begin // Assume 4 coins required for an item
                        next_state = DISPENSING_ITEM;
                    end
                end
            end
            DISPENSING_ITEM: begin
                next_state = IDLE; // Return to IDLE after dispensing
            end
        endcase
    end

    // Output logic and coin count update
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            coin_count <= 4'b0000;
        end else begin
            state <= current_state;
            if (current_state == COLLECTING_COINS) begin
                if (coin_inserted && coin_count < 4'b1111) begin
                    coin_count <= coin_count + 1;
                end else if (item_selected && coin_count >= 4'b0100) begin
                    coin_count <= 4'b0000; // Reset coin count after dispensing
                end
            end
        end
    end

endmodule

