    input clk, rst,
    input [15:0] a, b,
    output reg [15:0] out
);

    reg [7:0] stage1_sum;
    reg stage1_carry;
    reg [7:0] stage2_sum;
    reg stage2_carry;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            stage1_sum <= 8'b0;
            stage1_carry <= 1'b0;
            stage2_sum <= 8'b0;
            stage2_carry <= 1'b0;
            out <= 16'b0;
        end else begin
            // Stage 1: Compute lower 8 bits
            {stage1_carry, stage1_sum} <= a[7:0] + b[7:0];

            // Stage 2: Compute upper 8 bits
            {stage2_carry, stage2_sum} <= a[15:8] + b[15:8] + stage1_carry;

            // Output final result
            out <= {stage2_sum, stage1_sum};
        end
    end

