        coeff[1] = 8'h02;
        coeff[2] = 8'h03;
        coeff[3] = 8'h04;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 4; i = i + 1) begin
                x_delay[i] <= 8'b0;
                product[i] <= 16'b0;
            end
            sum_stage1 <= 16'b0;
            sum_stage2 <= 16'b0;
