            // Shift input data through delay line
            x_delay[0] <= x;
            for (i = 1; i < 4; i = i + 1) begin
                x_delay[i] <= x_delay[i-1];
            end

            // Stage 1: Multiply input data with coefficients
            for (i = 0; i < 4; i = i + 1) begin
                product[i] <= x_delay[i] * coeff[i];
            end

            // Stage 2: Accumulate partial sums
            sum_stage1 <= product[0] + product[1];
            sum_stage2 <= product[2] + product[3];

            // Stage 3: Final summation and output
            y <= sum_stage1 + sum_stage2;
        end
    end

