module compound_interest (
    input [15:0] P,
    input [7:0] r,
    input [7:0] n,
    output [31:0] A
);
    reg [31:0] base; // (1 + r) in fixed point
    reg [31:0] result; // Intermediate result
    reg [7:0] i; // Loop counter

    always @(*) begin
        // Calculate (1 + r) in fixed-point (assuming r is in Q8 format, i.e., integer part is 0 and fractional part is 8 bits)
        base = 16'd256 + r; // 256 represents 1.0 in Q8 format

        // Initialize result to 1.0 in fixed-point
        result = 16'd256;

        // Perform exponentiation (1 + r)^n
        for (i = 0; i < n; i = i + 1) begin
            result = (result * base) >> 8; // Fixed-point multiplication
        end

        // Final multiplication P * (1 + r)^n
        A = (P * result) >> 8; // Adjust for fixed-point representation
    end
endmodule

