module solar_radiation_average (
    input [7:0] r0, r1, r2, r3, r4, r5, r6, r7,
    output [7:0] avg_radiation
);
    reg [15:0] sum;
    reg [7:0] avg_temp;

    always @(*) begin
        sum = r0 + r1 + r2 + r3 + r4 + r5 + r6 + r7;
        avg_temp = sum >> 3; // Equivalent to division by 8
    end

    assign avg_radiation = avg_temp;

endmodule

